def verify_manifests():
    base=Path(__file__).parent
    for suite, filename in (("frozen", "review/manifests/frozen.json"), ("fresh", "review/manifests/fresh.json")):
        data=json.loads((base/filename).read_text(encoding="utf-8"))
        rows=data.get("cases", data.get("instances", data if isinstance(data,list) else []))
        indexed={r.get("manifest",r).get("case_id"):r for r in rows}
        for row in SLOTS:
            if row["suite"] != suite: continue
            source=indexed.get(row["case_id"])
            if source is None: raise ValueError("missing campaign case "+str(row["case_id"]))
            manifest=source.get("manifest",source)
            if digest(manifest) != row["manifest_hash"] or manifest != row["manifest"]: raise ValueError("manifest hash mismatch for "+row["slot"])
    return True
def slot_data(slot):
    # review/manifests/*.json are not uploaded to Qollab (top-level files only): verify against them when present
    # (local runs, tests); on Qollab verify each embedded manifest against its own frozen hash.
    if (Path(__file__).parent / "review" / "manifests" / "frozen.json").exists():
        verify_manifests()
    for row in SLOTS:
        if row["slot"] == slot:
            if digest(row["manifest"]) != row["manifest_hash"]:
                raise ValueError("embedded manifest hash mismatch for " + slot)
            return row
    raise ValueError("slot must be C02 through C25")
def build_slot(slot):
    row=slot_data(slot); m=row["manifest"]; params=m["generated_parameters"]
    edges=[tuple(e) for e in params["edges"]]; frame=params["frame_radians"]; angles=params["product_angles_radians"]
    circuits=[]
    for name in m["ordered_blocks"]:
        target=name.startswith("target"); qc=QuantumCircuit(4,4,name=name)
        append_preparation(qc,0,edges,frame,angles,"graph" if target else "product")
        maps=m["blocks"][name]["parity_maps"]
        if not name.endswith("_Z"):
            centers={p["generator"] for p in maps}
            for q,p in enumerate(frame): qc.rz(-float(p),q)
            for q in centers: qc.h(q)
        for q in range(4): qc.measure(q,q)
        circuits.append(qc)
    return circuits,m,row
